import asyncio
import inspect
from functools import wraps, partial
from fastapi.dependencies.models import Dependant

async def async_wrapper(func):
    @wraps(func)
    async def wrapper(*args, **kwargs):
        return await func(*args, **kwargs)
    return wrapper

def sync_func():
    return "hello"

def test_async_wrapper():
    # A synchronous function wrapped by an asynchronous wrapper
    # Note: the wrapper itself is async, so the resulting callable should be considered a coroutine callable
    wrapped = asyncio.run(async_wrapper(sync_func))
    dep = Dependant(call=wrapped)
    print(f"Test Async Wrapper: {dep.is_coroutine_callable=}")
    assert dep.is_coroutine_callable is True

def test_partial_wrapped():
    # A partial object wraps a function that has been wrapped via functools.wraps
    def base_func():
        return "hello"

    def wrapper(func):
        @wraps(func)
        def wrapped_func(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped_func

    wrapped_func = wrapper(base_func)
    # Now wrap it in partial
    partial_wrapped = partial(wrapped_func)

    # To make it a coroutine callable, let's make the base_func async
    async def async_base_func():
        return "hello"

    def async_wrapper_sync(func):
        @wraps(func)
        async def wrapped_func(*args, **kwargs):
            return await func(*args, **kwargs)
        return wrapped_func

    wrapped_async = async_wrapper_sync(async_base_func)
    partial_wrapped_async = partial(wrapped_async)

    dep = Dependant(call=partial_wrapped_async)
    print(f"Test Partial Wrapped Async: {dep.is_coroutine_callable=}")
    assert dep.is_coroutine_callable is True

if __name__ == "__main__":
    try:
        test_async_wrapper()
        print("test_async_wrapper passed")
        test_partial_wrapped()
        print("test_partial_wrapped passed")
        print("All tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")
        import traceback
        traceback.print_exc()
